<!doctype html><html lang="th"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>จัดการ · ShiftTrack</title><script src="assets/theme.js?v=brand-1"></script><link rel="stylesheet" href="assets/bootstrap.min.css"><link rel="stylesheet" href="assets/app.css?v=theme-2"><script src="assets/admin.js?v=publish-lock-1" defer></script><link rel="stylesheet" href="assets/brand.css?v=brand-9"><link rel="stylesheet" href="assets/training.css?v=training-20261020"><script src="assets/training-xlsx.js?v=1" defer></script><script src="assets/training-admin.js?v=training-20261020" defer></script><link rel="stylesheet" href="assets/training-layout.css?v=spacing-20261021"><script src="assets/training-layout.js?v=training-20261020" defer></script></head><body><header class="top"><a class="brand" href="./">ShiftTrack <small> / เจ้าของ</small></a><div class="d-flex gap-2 align-items-center"><button id="theme-toggle" type="button" class="theme-toggle" aria-label="เปลี่ยนเป็นโหมดมืด" aria-pressed="false"><span class="theme-symbol" aria-hidden="true">☀</span><span class="theme-label">Light</span></button><button id="logout" class="btn btn-outline-light btn-sm" hidden>ออกจากระบบ</button></div></header><main class="container page"><h1>ตารางเดียว สำหรับทั้งทีม</h1><p class="text-muted">จัดการสมาชิกและตรวจตารางก่อนเผยแพร่</p><div id="message" role="status" class="status" aria-live="polite"></div><form id="login" class="card p-4"><label for="password" class="form-label">รหัสผ่านเจ้าของ</label><input id="password" type="password" class="form-control" autocomplete="current-password" required><button class="btn btn-primary mt-3">เข้าสู่หน้าจัดการ</button></form>
<div id="workspace" hidden><section class="card p-4 mb-4"><h2>สมาชิก</h2><p>เพิ่มสมาชิกก่อนนำเข้าตาราง รหัสพนักงานต้องตรงกับรูป</p><div id="people" class="people-list"></div><form id="person-form" class="row g-3"><div class="col-md-3"><label for="person-id" class="form-label">รหัสพนักงาน</label><input id="person-id" class="form-control" maxlength="20" required></div><div class="col-md-5"><label for="person-name" class="form-label">ชื่อแสดง</label><input id="person-name" class="form-control" maxlength="100" required></div><div class="col-md-2"><label for="person-active" class="form-label">สถานะ</label><select id="person-active" class="form-select"><option value="1">เปิดใช้</option><option value="0">ปิดใช้</option></select></div><div class="col-md-8"><label for="person-photo" class="form-label">รูปบุคคล (ไม่เกิน 5 MB)</label><input id="person-photo" type="file" accept="image/png,image/jpeg,image/webp" class="form-control"></div><div class="col-md-4 d-flex align-items-end"><label><input id="remove-photo" type="checkbox"> ลบรูปเดิม ใช้อักษรย่อแทน</label></div><div><button class="btn btn-primary">บันทึกสมาชิก</button> <button id="person-clear" type="button" class="btn btn-outline-secondary">เพิ่มคนใหม่</button></div></form></section>
<section class="card p-4 mb-4"><h2>อัตราค่ากะ</h2><p>ช่องว่างหมายถึงยังไม่กำหนด ระบบจะไม่สรุปยอดเป็นเงินจนกำหนดครบสำหรับกะที่มีในเดือนนั้น</p><form id="rate-form"><div id="rates" class="row g-3"></div><button class="btn btn-primary mt-3">บันทึกอัตรา</button></form></section>
<section class="card p-4"><h2>นำเข้าและเผยแพร่ตาราง</h2><p>อ่านรูปบนเครื่องคุณ ตรวจทุกช่องก่อนเผยแพร่ การเผยแพร่จะแทนตารางทั้งหมดของเดือนที่เลือก</p><label for="import-month" class="form-label">เดือนของตาราง</label><input id="import-month" type="month" class="form-control mb-3"><label for="roster-image" class="form-label">รูปตารางที่เห็นเส้น รหัสพนักงาน และวันครบเดือน</label><input id="roster-image" type="file" accept="image/png,image/jpeg,image/webp" class="form-control"><img id="roster-preview" class="roster-preview" alt="รูปต้นฉบับสำหรับตรวจตาราง" hidden><div class="d-flex flex-wrap gap-2 my-3"><button id="read-image" class="btn btn-primary">อ่านรูปตาราง</button><button id="load-month" class="btn btn-outline-secondary">โหลดตารางที่เผยแพร่</button><button id="blank-month" class="btn btn-outline-secondary">สร้างตารางว่าง</button></div><div id="ocr-progress-wrap" hidden class="ocr-progress-wrap"><div id="progress" role="status" aria-live="polite"></div><progress id="ocr-progress" max="1" aria-label="ความคืบหน้าขั้นตอนอ่านภาพ"></progress><small>ความคืบหน้าของขั้นตอนปัจจุบัน · ต้องตรวจผลก่อนเผยแพร่</small></div><div id="review-wrap" hidden><p id="review-summary"></p><div class="table-responsive review-scroll"><table id="review" class="table table-bordered table-sm"></table></div><label class="d-block my-3"><input id="reviewed" type="checkbox"> ฉันตรวจรหัสพนักงานและกะทุกช่องแล้ว และยืนยันแทนตารางทั้งเดือน</label><button id="publish" class="btn btn-primary">เผยแพร่ให้ทีม</button></div></section></div></main></body></html>

